import React from 'react';

import { Link } from 'react-router-dom';

import PageLoader from '@components/PageLoader';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

import ObstacleListItem from './ObstacleListItem';
import { getObstaclesAsync } from '../../@services/obstacles.service';
import { IObstacle, ObstacleType } from '../../@types/obstacles.types';
import { addObstacleModalAsync, editObstacleModalAsync } from '../ObstacleModal/modalHelper';

interface IObstaclesByTypePageProps {
  type: 'peaks' | 'passes' | 'poi';
}
const getNameByType = (type: IObstaclesByTypePageProps['type']) => {
  if (type === 'peaks') return 'Вершины';
  if (type === 'passes') return 'Перевалы';
  return 'Точки интереса (POI)';
};
const getObstacleTypeByType = (type: IObstaclesByTypePageProps['type']) => {
  if (type === 'peaks') return ObstacleType.Peak;
  if (type === 'passes') return ObstacleType.Pass;
  return ObstacleType.Poi;
};
const ObstaclesByTypePage: React.FC<IObstaclesByTypePageProps> = ({ type }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IObstacle[]>([]);
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const list = await getObstaclesAsync({ type: getObstacleTypeByType(type) });
        setData(list);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [type]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert>{err}</PohAlert>;
  }

  const handleAdd = () => {
    addObstacleModalAsync({ type: getObstacleTypeByType(type) }).then((newObstacle) =>
      setData((ms) => [...ms, newObstacle]),
    );
  };

  const handleEdit = (obstacle: IObstacle) => {
    editObstacleModalAsync(obstacle).then((updatedObstacle) =>
      setData((ms) => ms.map((m) => (m.id === updatedObstacle.id ? updatedObstacle : m))),
    );
  };

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/obstacles', text: 'Локальные препятствия' },
          { href: `/obstacles/${type}`, text: getNameByType(type), active: true },
        ]}
      />
      <PohContainer>
        <header className="d-flex justify-content-between align-items-center d-print-none">
          <h3 className="mb-3">{getNameByType(type)}</h3>
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleAdd}>
            Добавить
          </PohButton>
        </header>
        <PohList
          data={data.map((obstacle) => {
            return {
              key: obstacle.id,
              content: <ObstacleListItem obstacle={obstacle} />,
              as: Link,
              to: `/obstacles/${type}/${obstacle.id}`,
              action: true,
              onContextMenu: (e: MouseEvent) => {
                e.preventDefault();
                handleEdit(obstacle);
              },
            };
          })}
        ></PohList>
      </PohContainer>
    </div>
  );
};

export default ObstaclesByTypePage;
